import{_ as e,c as a,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"LAN Play","description":"","frontmatter":{},"headers":[],"relativePath":"guide/lan-play.md","filePath":"guide/lan-play.md","lastUpdated":1780541175000}'),n={name:"guide/lan-play.md"};function s(l,o,r,c,d,h){return t(),a("div",null,[...o[0]||(o[0]=[i('<h1 id="lan-play" tabindex="-1">LAN Play <a class="header-anchor" href="#lan-play" aria-label="Permalink to &quot;LAN Play&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Gomoku supports playing against friends on the same local network. The LAN mode uses local network discovery or direct IP:port connections to let players find and join rooms.</p><p>Key features:</p><ul><li>Host a room (create a match) and advertise it on the local network</li><li>Automatic LAN discovery of available rooms</li><li>Join directly via IP and port</li><li>Optional chat and spectating (if enabled)</li></ul><h2 id="hosting-a-room-host" tabindex="-1">Hosting a Room (Host) <a class="header-anchor" href="#hosting-a-room-host" aria-label="Permalink to &quot;Hosting a Room (Host)&quot;">​</a></h2><ol><li>Open Gomoku and go to the &quot;Online / LAN&quot; page</li><li>Select &quot;Create Room&quot; or &quot;Start Hosting&quot;</li><li>Choose board size (e.g. 15x15 or 18x18) and match rules</li><li>Click &quot;Start Hosting&quot; — the app will show a port number (default chosen by the app)</li><li>Share the room name or your LAN IP with friends (example: <code>192.168.1.42</code>)</li></ol><p>The application will run a local service and broadcast the room information so other devices on the same network can discover it.</p><h2 id="joining-a-room-client" tabindex="-1">Joining a Room (Client) <a class="header-anchor" href="#joining-a-room-client" aria-label="Permalink to &quot;Joining a Room (Client)&quot;">​</a></h2><p>Automatic discovery</p><ol><li>On the &quot;Online / LAN&quot; page, refresh the room list</li><li>Select a discovered room and click &quot;Join&quot;</li></ol><p>Manual join</p><ol><li>Choose &quot;Manual Join&quot; or &quot;Enter Address&quot;</li><li>Enter the host&#39;s <code>IP:port</code> (for example <code>192.168.1.42:12345</code>)</li><li>Click &quot;Join&quot; and wait for the connection</li></ol><h2 id="macos-permissions-network-notes" tabindex="-1">macOS Permissions &amp; Network Notes <a class="header-anchor" href="#macos-permissions-network-notes" aria-label="Permalink to &quot;macOS Permissions &amp; Network Notes&quot;">​</a></h2><ul><li>Ensure Gomoku is allowed in <strong>System Settings → Privacy &amp; Security → Local Network</strong> so it can be discovered and communicate with peers.</li><li>Devices must be on the same Wi‑Fi network; some routers have client/AP isolation which prevents discovery.</li><li>If a firewall is enabled, allow Gomoku&#39;s incoming and outgoing traffic or open the configured port.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li>Can&#39;t discover rooms: confirm Local Network permission and disable AP isolation on the router.</li><li>Connection timed out joining a room: verify host IP/port and firewall settings.</li><li>Lag or stutter: try a wired connection or switch to a less congested network; close other bandwidth‑heavy applications.</li></ul><h2 id="logs-persistence" tabindex="-1">Logs &amp; Persistence <a class="header-anchor" href="#logs-persistence" aria-label="Permalink to &quot;Logs &amp; Persistence&quot;">​</a></h2><p>Room snapshots and service state are stored in the app data directory. In sandboxed builds the path example is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.gomoku/Data/Library/Application Support/com.w3cub.gomoku/</span></span></code></pre></div><p>See the project documentation <code>docs/macos-sandbox-paths.md</code> for more details on locating logs.</p><hr><p>If you want screenshots or a step‑by‑step walkthrough added to this guide, tell me and I will add them.</p>',23)])])}const m=e(n,[["render",s]]);export{u as __pageData,m as default};
